#!/usr/bin/env bash
# Generated by 'oa-gen scaffold-governance'.
# Override the oa-gen invocation by setting OA_GEN, e.g.:
#   OA_GEN="oa-gen" bash scripts/openapi-governance.sh all
#   OA_GEN="node /custom/path/cli.js" bash scripts/openapi-governance.sh all
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
if REPO_ROOT="$(git -C "$APP_DIR" rev-parse --show-toplevel 2>/dev/null)"; then
  :
else
  REPO_ROOT="$(cd "$APP_DIR/../.." && pwd)"
fi
if [[ -n "${OA_GEN:-}" ]]; then
  # Split on whitespace without pathname expansion. read -ra preserves
  # quoted segments better than the legacy unquoted array assignment.
  read -ra OA_GEN_CMD <<< "${OA_GEN}"
else
  OA_GEN_CMD=(node "$REPO_ROOT/packages/codegen/dist/cli/index.js")
fi

RAW="$APP_DIR/contracts/openapi.raw.yaml"
NORMALIZED="$APP_DIR/contracts/openapi.normalized.yaml"
UPGRADED="$APP_DIR/contracts/openapi.upgraded.yaml"
BASELINE="$APP_DIR/contracts/v1.openapi.yaml"
COLLECT_REPORT="$APP_DIR/contracts/openapi.collect-report.json"
TYPEGEN="$APP_DIR/src/generated/api-types.ts"
RUNTIME_OPENAPI_URL="http://localhost:3000/openapi.json"

# source_openapi runs the --source-command captured at scaffold time as
# verbatim shell. Treat its body as trusted input from whoever ran scaffold;
# review changes here the same way you would review any committed shell
# script before running 'all'.
source_openapi() {
  (cd "$APP_DIR" && pnpm export:openapi)
}

collect_openapi() {
  source_openapi
  "${OA_GEN_CMD[@]}" collect \
    --spec "$RAW" \
    --normalized "$NORMALIZED" \
    --upgraded "$UPGRADED" \
    --report "$COLLECT_REPORT" \
    --profile nestjs-swagger
}

require_baseline() {
  test -f "$BASELINE" || {
    echo "missing baseline: $BASELINE" >&2
    echo "hint: run '$0 update-baseline' after inspecting '$NORMALIZED'." >&2
    exit 1
  }
}

case "${1:-all}" in
  collect)
    collect_openapi
    ;;
  check)
    collect_openapi
    require_baseline
    "${OA_GEN_CMD[@]}" check-artifact --head "${NORMALIZED}" --artifact "$BASELINE" --format human
    ;;
  review)
    collect_openapi
    require_baseline
    "${OA_GEN_CMD[@]}" review --base "$BASELINE" --head "${NORMALIZED}" --artifact "$BASELINE" --format markdown
    ;;
  typegen)
    collect_openapi
    mkdir -p "$(dirname "$TYPEGEN")"
    "${OA_GEN_CMD[@]}" typegen --spec "${NORMALIZED}" --output "$TYPEGEN"
    ;;
  inventory)
    collect_openapi
    "${OA_GEN_CMD[@]}" inventory --spec "${UPGRADED}" --format markdown
    ;;
  validate-upgraded)
    collect_openapi
    "${OA_GEN_CMD[@]}" validate --spec "${UPGRADED}"
    ;;
  drift)
    collect_openapi
    test -n "$RUNTIME_OPENAPI_URL" || { echo "runtimeOpenApiUrl is not configured" >&2; exit 1; }
    "${OA_GEN_CMD[@]}" drift --runtime-openapi-url "$RUNTIME_OPENAPI_URL" --managed-openapi "${NORMALIZED}" --format markdown
    ;;
  review-bundle)
    collect_openapi
    require_baseline
    "${OA_GEN_CMD[@]}" review-bundle \
      --base "$BASELINE" \
      --head "${NORMALIZED}" \
      --artifact "$BASELINE" \
      --inventory \
      --format markdown
    ;;
  update-baseline)
    collect_openapi
    mkdir -p "$(dirname "$BASELINE")"
    cp "$NORMALIZED" "$BASELINE"
    echo "baseline updated: $BASELINE"
    ;;
  all)
    collect_openapi
    require_baseline
    "${OA_GEN_CMD[@]}" check-artifact --head "${NORMALIZED}" --artifact "$BASELINE" --format human
    "${OA_GEN_CMD[@]}" review --base "$BASELINE" --head "${NORMALIZED}" --artifact "$BASELINE" --format markdown
    mkdir -p "$(dirname "$TYPEGEN")"
    "${OA_GEN_CMD[@]}" typegen --spec "${NORMALIZED}" --output "$TYPEGEN"
    "${OA_GEN_CMD[@]}" validate --spec "${UPGRADED}"
    ;;
  *)
    echo "usage: $0 [collect|check|review|review-bundle|typegen|inventory|validate-upgraded|drift|update-baseline|all]" >&2
    exit 1
    ;;
esac
